    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "WebAppSG"
  }
}

resource "aws_iam_role" "web_app_role" {
  name = "web_app_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "WebAppRole"
  }
}

resource "aws_iam_instance_profile" "web_app_instance_profile" {
  name = "web_app_instance_profile"
  role = aws_iam_role.web_app_role.name
}

resource "aws_launch_template" "web_app_launch_template" {
  name = "web_app_launch_template"

  image_id      = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.web_app_instance_profile.name
  }

  security_group_names = [aws_security_group.web_app_sg.name]

  tags = {
    Name = "WebAppLaunchTemplate"
  }
}

resource "aws_autoscaling_group" "web_app_asg" {
  name                 = "web_app_asg"
  launch_template {
    id      = aws_launch_template.web_app_launch_template.id
    version = "$Latest"
  }
  vpc_zone_identifier  = [aws_subnet.web_app_subnet.id]
  min_size             = 1
  max_size             = 3
  desired_capacity     = 2

  tags = [
    {
      key                 = "Name"
      value               = "WebAppInstance"
      propagate_at_launch = true
    }
  ]
}

resource "aws_lb" "web_app_lb" {
  name               = "web-app-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.web_app_subnet.id]

  tags = {
    Name = "WebAppLB"
  }
}

resource "aws_lb_target_group" "web_app_target_group" {
  name     = "web-app-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.web_app_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "WebAppTargetGroup"
  }
}

resource "aws_lb_listener" "web_app_listener" {
  load_balancer_arn = aws_lb.web_app_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web_app_target_group.arn
  }

  tags = {
    Name = "WebAppListener"
  }
}

resource "aws_ebs_volume" "web_app_ebs_volume" {
  availability_zone = aws_subnet.web_app_subnet.availability_zone
  size              = 20
  type              = "gp2"

  tags = {
    Name = "WebAppEBSVolume"
  }
}

resource "aws_ebs_attachment" "web_app_ebs_attachment" {
  device_name = "/dev/sdh"
  volume_id   = aws_ebs_volume.web_app_ebs_volume.id
  instance_id = aws_autoscaling_group.web_app_asg.instances[0].id

  depends_on = [aws_autoscaling_group.web_app_asg]
}
