### Description

This Terraform program creates an AWS Elastic Beanstalk application with an application version lifecycle. It includes the necessary IAM role and policy attachments required for Elastic Beanstalk operations. The program ensures that the resources are created in the correct order, respecting their dependencies.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "beanstalk_service_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.beanstalk_service_role.name
}

resource "aws_elastic_beanstalk_application" "my_elastic_beanstalk_app" {
  name = "my-elastic-beanstalk-app"

  appversion_lifecycle {
    service_role       = aws_iam_role.beanstalk_service_role.arn
    max_count          = 10
    delete_source_from_s3 = true
  }
}
```

