### Description
This Terraform program creates a basic AWS CodeBuild project with an associated IAM role. The IAM role is configured with the necessary permissions for CodeBuild operations. The CodeBuild project is set up to use a GitHub source, although the specific GitHub source configuration is not included in this basic setup.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "codebuild-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
            "s3:GetObject",
            "s3:PutObject",
            "ec2:CreateNetworkInterface",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeVpcs"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_codebuild_project" "basic_codebuild_project" {
  name         = "basic-codebuild-project"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `codebuild-role` is created with an assume role policy that allows CodeBuild to assume the role. An inline policy is added to grant necessary permissions for CodeBuild operations, including logging, S3 access, and EC2 network interface management.
- **CodeBuild Project**: A CodeBuild project named `basic-codebuild-project` is created. It uses the IAM role created earlier. The source is configured to use a GitHub repository, and the environment is set up with a small Linux container using the Amazon Linux 2 image. No artifacts are specified for simplicity.

