### Description
This Terraform program creates an AWS Lex bot named "order_pizzas_bot" for ordering pizzas. It also creates an associated intent named "order_pizzas_intent". The bot is configured with a confidence threshold of 0.5 for NLU (Natural Language Understanding) intent detection. The intent includes necessary slots and prompts to handle pizza ordering.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "order_pizzas_intent" {
  name        = "order_pizzas_intent"
  description = "Intent to order pizzas"

  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order me a pizza please"
  ]

  slot {
    name               = "PizzaType"
    slot_constraint    = "Required"
    slot_type          = "AMAZON.FoodItem"
    slot_type_version  = "$$LATEST"
    priority           = 1
    sample_utterances  = ["Margherita", "Pepperoni", "Veggie"]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content     = "What type of pizza would you like?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name               = "Quantity"
    slot_constraint    = "Required"
    slot_type          = "AMAZON.NUMBER"
    slot_type_version  = "$$LATEST"
    priority           = 2
    sample_utterances  = ["One", "Two", "Three"]
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content     = "How many pizzas would you like?"
        content_type = "PlainText"
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content     = "You want to order {Quantity} {PizzaType} pizzas. Is that correct?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content     = "Okay, I will not place your order."
      content_type = "PlainText"
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "order_pizzas_bot" {
  name                        = "order_pizzas_bot"
  child_directed              = false
  nlu_intent_confidence_threshold = 0.5

  intent {
    intent_name    = aws_lex_intent.order_pizzas_intent.name
    intent_version = "$LATEST"
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content     = "I didn't understand you, could you please repeat that?"
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content     = "Sorry, I am not able to assist with that."
      content_type = "PlainText"
    }
  }

  idle_session_ttl_in_seconds = 300
  locale                      = "en-US"
  process_behavior            = "BUILD"
}
```

