### Description
This Terraform program sets up an Amazon Kendra data source with a proxy configuration. It includes the creation of a Kendra index, an IAM role with necessary permissions, and a Secrets Manager secret to store proxy authentication credentials. The data source is configured to use these resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kendra_index" "kendra_index" {
  name       = "my-kendra-index"
  role_arn   = aws_iam_role.kendra_role.arn
  edition    = "ENTERPRISE_EDITION"
  description = "My Kendra Index"

  capacity_units {
    query_capacity_units   = 2
    storage_capacity_units = 50
  }

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonKendraFullAccess"
  ]
}

resource "aws_secretsmanager_secret" "proxy_credentials_secret" {
  name = "kendra-proxy-credentials"
}

resource "aws_secretsmanager_secret_version" "proxy_credentials_secret_version" {
  secret_id     = aws_secretsmanager_secret.proxy_credentials_secret.id
  secret_string = jsonencode({
    username = "proxy-user"
    password = "proxy-password"
  })
}

resource "aws_kendra_data_source" "kendra_data_source" {
  index_id = aws_kendra_index.kendra_index.id
  name     = "my-kendra-data-source"
  type     = "WEBCRAWLER"
  role_arn = aws_iam_role.kendra_role.arn

  configuration {
    web_crawler_configuration {
      proxy_configuration {
        credentials = aws_secretsmanager_secret.proxy_credentials_secret.arn
        host        = "proxy.example.com"
        port        = 8080
      }

      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }
    }
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Kendra Index**: An Amazon Kendra index is created with specified capacity units and user group resolution configuration.
3. **IAM Role**: An IAM role is created with the necessary permissions for Kendra. The role assumes the `AmazonKendraFullAccess` managed policy.
4. **Secrets Manager Secret**: A Secrets Manager secret is created to store proxy authentication credentials.
5. **Secrets Manager Secret Version**: A version of the secret is created with the actual credentials.
6. **Kendra Data Source**: A Kendra data source is created with a web crawler configuration that includes a proxy configuration using the Secrets Manager secret.

