    PolicyName      = "example-traffic-policy",
    TrafficPolicyDocument = {
      Version = "2015-10-01",
      Rules   = {
        Rule_1 = {
          Type = "failover",
          FailoverRoutingConfig = {
            PrimaryTrafficPolicyId = "primary-policy-id",
