### Description
This Terraform program creates a 2-node Amazon Redshift cluster with concurrency scaling limited to 60 minutes. The program includes the necessary configuration for the Redshift cluster, including setting the cluster type to `multi-node` and specifying the node type. Additionally, it sets up the IAM role required for concurrency scaling.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "database_name" {
  description = "The name of the database to be created"
  default     = "mydb"
}

variable "master_username" {
  description = "The username for the database administrator"
  default     = "admin"
}

variable "master_password" {
  description = "The password for the database administrator"
  default     = "SecurePassword123!"
}

resource "aws_iam_role" "redshift_concurrency_scaling_role" {
  name = "redshift-concurrency-scaling-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_concurrency_scaling_policy" {
  name        = "redshift-concurrency-scaling-policy"
  description = "Policy for Redshift concurrency scaling"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:PauseCluster",
          "redshift:ResumeCluster"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_concurrency_scaling_policy_attachment" {
  role       = aws_iam_role.redshift_concurrency_scaling_role.name
  policy_arn = aws_iam_policy.redshift_concurrency_scaling_policy.arn
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier      = var.cluster_identifier
  node_type               = var.node_type
  cluster_type            = "multi-node"
  database_name           = var.database_name
  master_username         = var.master_username
  master_password         = var.master_password
  default_iam_role_arn    = aws_iam_role.redshift_concurrency_scaling_role.arn
  automated_snapshot_retention_period = 7
  allow_version_upgrade   = true
  apply_immediately       = true

  timeouts {
    create = "60m"
    update = "60m"
    delete = "60m"
  }
}
```

This Terraform configuration sets up a Redshift cluster with two nodes, configures IAM roles for concurrency scaling, and limits the concurrency scaling operations to 60 minutes. The cluster is deployed in the `us-west-2` region, and default values are provided for various parameters.

