}

resource "aws_iam_role" "lambda_role" {
  name = "redshift-snapshot-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_role.name
}

resource "aws_iam_policy" "redshift_snapshot_policy" {
  name        = "redshift-snapshot-policy"
  description = "Policy to allow Lambda to create Redshift snapshots"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:CreateClusterSnapshot",
          "redshift:DescribeClusters"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_policy" {
  policy_arn = aws_iam_policy.redshift_snapshot_policy.arn
  role       = aws_iam_role.lambda_role.name
}

resource "aws_lambda_function" "redshift_snapshot_lambda" {
  filename         = "lambda_function_payload.zip"
  function_name    = "redshift-snapshot-lambda"
  handler          = "index.handler"
  role             = aws_iam_role.lambda_role.arn
  runtime          = "python3.8"
  source_code_hash = filebase64sha256("lambda_function_payload.zip")

  environment {
    variables = {
      CLUSTER_IDENTIFIER = var.cluster_identifier
      SNAPSHOT_IDENTIFIER_PREFIX = var.snapshot_identifier_prefix
    }
  }
}

resource "aws_cloudwatch_event_rule" "redshift_snapshot_rule" {
  name                = "redshift-snapshot-rule"
  schedule_expression = "cron(0 */12 * * ? *)"
}

resource "aws_cloudwatch_event_target" "redshift_snapshot_target" {
  rule      = aws_cloudwatch_event_rule.redshift_snapshot_rule.name
  target_id = "redshift-snapshot-target"
  arn       = aws_lambda_function.redshift_snapshot_lambda.invoke_arn
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = var.cluster_identifier
  node_type          = var.node_type
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = var.master_password
  cluster_type       = "single-node"
}
