    bucket_name = aws_s3_bucket.redshift_logs.bucket
    s3_key_prefix = "redshift-logs/"
  }

  timeouts {
    create = "60m"
    update = "60m"
    delete = "60m"
  }
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

