### Description

This Terraform program sets up a primary Redshift cluster in the `us-east-1` region and a secondary Redshift cluster in the `us-east-2` region. The secondary cluster is configured to replicate data from the primary cluster. The program includes the necessary IAM roles and policies to manage access between the clusters for replication.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_identifier_primary" {
  description = "The identifier for the primary Redshift cluster"
  default     = "primary-redshift-cluster"
}

variable "cluster_identifier_secondary" {
  description = "The identifier for the secondary Redshift cluster"
  default     = "secondary-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift clusters"
  default     = "dc2.large"
}

variable "database_name" {
  description = "The name of the database to be created"
  default     = "mydatabase"
}

variable "master_username" {
  description = "The username for the database administrator"
  default     = "admin"
}

variable "master_password" {
  description = "The password for the database administrator"
  default     = "SecurePassword123!"
}

resource "aws_iam_role" "redshift_replication_role" {
  name = "redshift-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_replication_policy" {
  name        = "redshift-replication-policy"
  description = "Policy for Redshift replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:CreateClusterSnapshot",
          "redshift:DescribeClusterSnapshots",
          "redshift:CopyClusterSnapshot"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_replication_policy_attachment" {
  role       = aws_iam_role.redshift_replication_role.name
  policy_arn = aws_iam_policy.redshift_replication_policy.arn
}

resource "aws_redshift_cluster" "primary_redshift_cluster" {
  cluster_identifier = var.cluster_identifier_primary
  node_type          = var.node_type
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = var.master_password
  cluster_type       = "multi-node"
  iam_roles          = [aws_iam_role.redshift_replication_role.arn]
}

resource "aws_redshift_cluster" "secondary_redshift_cluster" {
  cluster_identifier = var.cluster_identifier_secondary
  node_type          = var.node_type
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = var.master_password
  cluster_type       = "multi-node"
  iam_roles          = [aws_iam_role.redshift_replication_role.arn]

  snapshot_copy {
    destination_region = "us-east-2"
    retention_period   = 7
  }

  depends_on = [aws_redshift_cluster.primary_redshift_cluster]
}
```

This Terraform configuration sets up the primary Redshift cluster in `us-east-1` and the secondary Redshift cluster in `us-east-2`. The secondary cluster is configured to replicate data from the primary cluster using the specified IAM role and policy.

