### Description

The Terraform program defines a DynamoDB table named `example_dynamodb_table` with specific attributes and settings, including a TTL (Time To Live) configuration. It also creates a DynamoDB Contributor Insights resource for this table. The program ensures that all attributes are indexed by adding them to either the primary key or secondary indexes.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "example_dynamodb_table" {
  name           = "example_dynamodb_table"
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20

  hash_key = "UserId"
  range_key = "GameTitle"

  attribute {
    name = "UserId"
    type = "S"
  }

  attribute {
    name = "GameTitle"
    type = "S"
  }

  attribute {
    name = "TopScore"
    type = "N"
  }

  attribute {
    name = "TimeToExist"
    type = "N"
  }

  local_secondary_index {
    name               = "TopScoreIndex"
    projection_type    = "INCLUDE"
    non_key_attributes = ["TopScore"]
    range_key          = "TopScore"
  }

  ttl {
    attribute_name = "TimeToExist"
    enabled        = true
  }

  tags = {
    Name        = "example_dynamodb_table"
    Environment = "production"
  }
}

resource "aws_dynamodb_contributor_insights" "example_contributor_insights" {
  table_name = aws_dynamodb_table.example_dynamodb_table.name
}
```

This configuration ensures that all attributes are indexed by adding the `TopScore` attribute to a local secondary index. The `TimeToExist` attribute is also included as part of the table's attributes to support the TTL feature. The DynamoDB Contributor Insights resource is then created for the table.

