}

resource "aws_subnet" "msk_subnet_az3" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-east-1c"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_kms_key" "msk_kms_key" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 10
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "msk_broker_logs"
  retention_in_days = 30
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-broker-logs-bucket-${random_string.suffix.result}"
}

resource "aws_s3_bucket_acl" "msk_logs_bucket_acl" {
  bucket = aws_s3_bucket.msk_logs_bucket.id
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

data "aws_iam_policy_document" "firehose_assume_role_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "firehose_role" {
  name               = "firehose_msk_logs_role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role_policy.json
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.msk_subnet_az1.id,
      aws_subnet.msk_subnet_az2.id,
      aws_subnet.msk_subnet_az3.id
    ]
    instance_type = "kafka.m5.large"
    security_groups = [
      aws_security_group.msk_sg.id
    ]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
      firehose {
        delivery_stream = "msk-firehose-delivery-stream"
        enabled         = true
      }
      s3 {
        bucket = aws_s3_bucket.msk_logs_bucket.bucket
        prefix = "logs/"
      }
    }
  }
}
