### Description:
This Terraform program creates a serverless Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The configuration includes the necessary VPC settings, client authentication using IAM, and basic tagging.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet_az1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "msk_subnet_az2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = "my-msk-serverless-cluster"

  vpc_config {
    subnet_ids       = [aws_subnet.msk_subnet_az1.id, aws_subnet.msk_subnet_az2.id]
    security_group_ids = [aws_security_group.msk_sg.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  tags = {
    Name = "MyMSKServerlessCluster"
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **VPC and Subnets**: A VPC is created with two subnets in different availability zones (`us-east-1a` and `us-east-1b`).
3. **Security Group**: A security group is created to allow inbound traffic on port 9098 (used for Kafka communication) from within the VPC and outbound traffic to any destination.
4. **MSK Serverless Cluster**: The serverless MSK cluster is created with the specified VPC configuration and client authentication using IAM. The cluster is tagged for easy identification.

