### Description
This Terraform program creates an Aurora PostgreSQL cluster within an AWS environment. It includes the necessary components such as a VPC, subnets, security groups, an internet gateway, route tables, and IAM roles. The Aurora cluster and its instance are configured to use these components.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "aurora_postgresql_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "AuroraPostgreSQLVPC"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "aurora_postgresql_igw" {
  vpc_id = aws_vpc.aurora_postgresql_vpc.id
  tags = {
    Name = "AuroraPostgreSQLIGW"
  }
}

# Create a Subnet
resource "aws_subnet" "aurora_postgresql_subnet" {
  vpc_id            = aws_vpc.aurora_postgresql_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "AuroraPostgreSQLSubnet"
  }
}

# Create a DB Subnet Group
resource "aws_db_subnet_group" "aurora_postgresql_subnet_group" {
  name       = "aurora-postgresql-subnet-group"
  subnet_ids = [aws_subnet.aurora_postgresql_subnet.id]
  tags = {
    Name = "AuroraPostgreSQLDBSubnetGroup"
  }
}

# Create a Security Group
resource "aws_security_group" "aurora_postgresql_sg" {
  vpc_id = aws_vpc.aurora_postgresql_vpc.id
  name   = "aurora-postgresql-sg"
  description = "Security group for Aurora PostgreSQL"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AuroraPostgreSQLSG"
  }
}

# Create an IAM Role
resource "aws_iam_role" "aurora_postgresql_role" {
  name = "aurora-postgresql-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a Policy to the IAM Role
resource "aws_iam_role_policy_attachment" "aurora_postgresql_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSClusterRole"
  role       = aws_iam_role.aurora_postgresql_role.name
}

# Create a Route Table
resource "aws_route_table" "aurora_postgresql_rt" {
  vpc_id = aws_vpc.aurora_postgresql_vpc.id
  tags = {
    Name = "AuroraPostgreSQLRouteTable"
  }
}

# Add a Route to the Route Table
resource "aws_route" "aurora_postgresql_route" {
  route_table_id         = aws_route_table.aurora_postgresql_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.aurora_postgresql_igw.id
}

# Create an Aurora PostgreSQL Cluster
resource "aws_rds_cluster" "aurora_postgresql_cluster" {
  engine              = "aurora-postgresql"
  engine_version      = "13.7"
  cluster_identifier  = "aurora-postgresql-cluster"
  master_username     = "admin"
  master_password     = "password123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name = aws_db_subnet_group.aurora_postgresql_subnet_group.name
  iam_database_authentication_enabled = true
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.aurora_postgresql_sg.id]
  db_cluster_parameter_group_name = "default.aurora-postgresql13"
  tags = {
    Name = "AuroraPostgreSQLCluster"
  }
}

# Create an Aurora PostgreSQL Instance
resource "aws_rds_cluster_instance" "aurora_postgresql_instance" {
  identifier         = "aurora-postgresql-instance"
  cluster_identifier = aws_rds_cluster.aurora_postgresql_cluster.id
  instance_class     = "db.t3.medium"
  engine             = aws_rds_cluster.aurora_postgresql_cluster.engine
  engine_version     = aws_rds_cluster.aurora_postgresql_cluster.engine_version
  db_subnet_group_name = aws_db_subnet_group.aurora_postgresql_subnet_group.name
  db_parameter_group_name = "default.aurora-postgresql13"
  tags = {
    Name = "AuroraPostgreSQLInstance"
  }
}
```

This Terraform configuration sets up an Aurora PostgreSQL cluster with the necessary networking and security configurations. Adjust the `master_username`, `master_password`, and other parameters as needed for your specific use case.

