To resolve the authentication failure error, we need to ensure that the AWS provider has the necessary credentials configured. This can be done by setting up the AWS provider with the appropriate access key, secret key, and region. Since the error message indicates an authentication failure, we need to provide valid AWS credentials.

Here is the corrected Terraform configuration:

```hcl
provider "aws" {
  region     = "us-west-2"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}

variable "aws_access_key" {
  description = "AWS access key"
  type        = string
  sensitive   = true
}

variable "aws_secret_key" {
  description = "AWS secret key"
  type        = string
  sensitive   = true
}

resource "aws_vpc" "my_vpc" {
  cidr_block           = "172.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "my-vpc"
  }
}

resource "aws_subnet" "my_subnet" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "172.16.10.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "my-subnet"
  }
}

data "aws_ami" "ubuntu_20_04_ami" {
  most_recent = true
  owners      = ["099720109477"]  # Canonical's AWS account ID

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_instance" "my_instance" {
  ami           = data.aws_ami.ubuntu_20_04_ami.id
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.my_subnet.id

  tags = {
    Name = "my-instance"
  }
}
```

In this configuration, I have added two variables `aws_access_key` and `aws_secret_key` to store the AWS credentials. These variables are marked as sensitive to ensure they are not exposed in logs or plans. You need to provide the actual AWS access key and secret key when running Terraform.

