  # Ensure the log bucket can receive logs
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Principal = "*",
        Action   = "s3:GetBucketAcl",
        Resource = "${aws_s3_bucket.log_bucket.arn}"
      },
      {
        Effect   = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action   = "s3:PutObject",
        Resource = "${aws_s3_bucket.log_bucket.arn}/my-main-bucket/*"
      }
    ]
  })
}

resource "aws_s3_bucket" "log_bucket" {
  bucket = "my-log-bucket-${random_string.bucket_suffix.result}"
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_logging" "main_bucket_logging" {
  bucket      = aws_s3_bucket.main_bucket.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "logs/"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

This configuration ensures that the log bucket has the necessary permissions to receive logs from the main bucket. The `random_string` resource generates a suffix to ensure the bucket names are unique. The `aws_s3_bucket_logging` resource configures the logging for the main bucket to store logs in the log bucket.

