  bucket = aws_s3_bucket.autograder_results_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:PutObject"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.codebuild_role.arn
        }
        Resource = [
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      }
    ]
  })
}

