### Description
The Terraform configuration defines an infrastructure for an autograder that runs students' code stored on GitHub and stores the results in an S3 bucket. The configuration includes an S3 bucket for storing results, an IAM role and policy for AWS CodeBuild, and a CodeBuild project that fetches code from GitHub, executes it, and uploads the results to the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "Autograder Results Bucket"
    Environment = "Production"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

data "aws_iam_policy_document" "autograder_assume_role_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "autograder_codebuild_role" {
  name               = "autograder-codebuild-role"
  assume_role_policy = data.aws_iam_policy_document.autograder_assume_role_policy.json
}

resource "aws_iam_policy_document" "autograder_codebuild_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      "arn:aws:logs:*:*:log-group:/aws/codebuild/*",
      "arn:aws:s3:::${aws_s3_bucket.autograder_results_bucket.bucket}/*",
      "arn:aws:s3:::${aws_s3_bucket.autograder_results_bucket.bucket}"
    ]
  }
}

resource "aws_iam_role_policy" "autograder_codebuild_policy" {
  name   = "autograder-codebuild-policy"
  role   = aws_iam_role.autograder_codebuild_role.id
  policy = data.aws_iam_policy_document.autograder_codebuild_policy.json
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  description  = "CodeBuild project for running autograder"
  service_role = aws_iam_role.autograder_codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  build_timeout = 60
}
```

