```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC for the autograder environment
resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Internet Gateway to allow outbound traffic from the VPC
resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
}

# Route table for public subnets
resource "aws_route_table" "autograder_public_rt" {
  vpc_id = aws_vpc.autograder_vpc.id
}

# Route to the Internet Gateway
resource "aws_route" "autograder_public_route" {
  route_table_id         = aws_route_table.autograder_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

# Public subnet for the autograder environment
resource "aws_subnet" "autograder_public_subnet" {
  vpc_id                  = aws_vpc.autograder_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

# Associate the main route table with the public subnet
resource "aws_main_route_table_association" "autograder_main_rta" {
  vpc_id         = aws_vpc.autograder_vpc.id
  route_table_id = aws_route_table.autograder_public_rt.id
}

# Security group to control inbound and outbound traffic
resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id
  name   = "autograder_sg"

  # Allow SSH ingress for debugging
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Allow all egress traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# EC2 instance to run the autograder
resource "aws_instance" "autograder_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Ubuntu Server 20.04 LTS
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.autograder_public_subnet.id
  security_groups = [aws_security_group.autograder_sg.name]

  tags = {
    Name = "autograder_instance"
  }
}

# IAM role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder_codebuild_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy for CodeBuild
resource "aws_iam_policy" "autograder_codebuild_policy" {
  name        = "autograder_codebuild_policy"
  description = "Policy for CodeBuild to access S3 and EC2"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::autograder-results-bucket/*"
        ]
      },
      {
        Action = [
          "ec2:Describe*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "autograder_codebuild_policy_attach" {
  policy_arn = aws_iam_policy.autograder_codebuild_policy.arn
  role       = aws_iam_role.autograder_codebuild_role.name
}

# S3 bucket to store autograding results
resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket"
  acl    = "private"
}

# CodeBuild project to build and test student code
resource "aws_codebuild_project" "autograder_codebuild" {
  name         = "autograder_codebuild"
  service_role = aws_iam_role.autograder_codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    auth {
      type = "OAUTH"
    }
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type         = "LINUX_CONTAINER"
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_public_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }
}
