Description:
The Terraform program defines an AWS infrastructure setup for storing code build output in an S3 bucket, creating a VPC with a subnet, configuring a security group to block internet access, and setting up an AWS CodeBuild project linked to the VPC resources. The program includes necessary IAM roles and policies for the CodeBuild project to function correctly.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = "codebuild-output-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "no_internet_access_sg" {
  vpc_id = aws_vpc.main_vpc.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc_security_group_vpc_association" "sg_vpc_association" {
  vpc_id            = aws_vpc.main_vpc.id
  security_group_id = aws_security_group.no_internet_access_sg.id
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "codebuild-policy"
  role = aws_iam_role.codebuild_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "ec2:CreateNetworkInterfacePermission"
        Effect = "Allow"
        Resource = "arn:aws:ec2:us-west-2:*:network-interface/*"
        Condition = {
          StringEquals = {
            "ec2:Subnet" = aws_subnet.main_subnet.arn
          }
        }
      }
    ]
  })
}

resource "aws_codebuild_project" "students_codebuild_project" {
  name         = "students-codebuild-project"
  service_role = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type   = "S3"
    location = "${aws_s3_bucket.codebuild_output_bucket.bucket}/artifacts"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type         = "GITHUB"
    location     = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id             = aws_vpc.main_vpc.id
    subnets            = [aws_subnet.main_subnet.id]
    security_group_ids = [aws_security_group.no_internet_access_sg.id]
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
