    aws_api_gateway_integration.upload_integration,
    aws_api_gateway_integration.random_integration
  ]

  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  triggers    = {
    redeployment = sha1(join(",", [
      aws_api_gateway_integration.upload_integration.uri,
      aws_api_gateway_integration.random_integration.uri
    ]))
  }
}

resource "aws_api_gateway_stage" "cat_pictures_stage" {
  deployment_id = aws_api_gateway_deployment.cat_pictures_deployment.id
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name    = "prod"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
