### Description
The Terraform program defines an infrastructure for hosting a web service that allows users to upload cat pictures and retrieve random cat pictures. The service uses AWS DynamoDB to store metadata about the uploaded cat pictures, AWS S3 to store the actual images, and AWS Lambda functions to handle the upload logic. AWS API Gateway is used to expose the API endpoints for these operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "cat_pictures_table" {
  name           = "cat-pictures-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_policy" "s3_dynamodb_access" {
  name        = "s3-dynamodb-access-policy"
  description = "Policy to allow Lambda to access S3 and DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:DeleteItem"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_dynamodb_table.cat_pictures_table.arn}"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_dynamodb_access_attachment" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.s3_dynamodb_access.arn
}

resource "aws_lambda_function" "upload_cat_picture_lambda" {
  function_name = "upload-cat-picture-lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function_payload.zip"

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = aws_dynamodb_table.cat_pictures_table.name
      S3_BUCKET_NAME      = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_lambda_permission" "upload_cat_picture_permission" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload_cat_picture_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_pictures_api.execution_arn}/*/*"
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
}

resource "aws_api_gateway_method" "upload_method" {
  authorization = "NONE"
  http_method   = "POST"
  resource_id   = aws_api_gateway_resource.upload_resource.id
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
}
```

This configuration sets up the necessary AWS resources to create a web service for uploading and retrieving cat pictures. It includes a DynamoDB table for storing metadata, an S3 bucket for storing images, a Lambda function for handling uploads, and an API Gateway for exposing the API endpoints.

