### Terraform Program Description

This Terraform program sets up an AWS infrastructure consisting of an EventBridge rule named "cron" that triggers a Lambda function every day at 7 UTC. The Lambda function is configured to execute a deployment package located at "./supplement/lambda_func.zip". The program includes the necessary IAM roles and permissions to ensure that the EventBridge rule can invoke the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify a valid AWS region
}

# IAM Policy Document for Lambda execution role
data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# IAM Role for Lambda execution
resource "aws_iam_role" "iam_for_lambda" {
  name               = "iam_for_lambda"
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json
}

# Lambda Function
resource "aws_lambda_function" "lambda_function" {
  function_name = "lambda_function_name"
  role          = aws_iam_role.iam_for_lambda.arn
  handler       = "index.test"
  runtime       = "nodejs18.x"
  filename      = "./supplement/lambda_func.zip"
}

# EventBridge Rule
resource "aws_cloudwatch_event_rule" "cron_rule" {
  name                = "cron"
  schedule_expression = "cron(0 7 * * ? *)"
}

# EventBridge Target to invoke Lambda function
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.cron_rule.name
  target_id = "lambda_target"
  arn       = aws_lambda_function.lambda_function.arn
}

# Permission for EventBridge to invoke Lambda function
resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lambda_function.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron_rule.arn
}
```

This Terraform configuration ensures that the EventBridge rule is correctly set up to trigger the Lambda function daily at 7 UTC, with the necessary IAM roles and permissions in place.

