### Description

This Terraform program sets up the infrastructure for a video streaming site with multiple servers to balance load using AWS Load Balancing. The program creates a VPC, a public subnet, a security group, an Application Load Balancer (ALB), a target group, and two EC2 instances. The ALB distributes incoming traffic to the EC2 instances via the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "video_streaming_subnet_public" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  name   = "video-streaming-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.video_streaming_subnet_public.id]
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

resource "aws_instance" "video_streaming_server_1" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_subnet_public.id
  security_groups = [aws_security_group.video_streaming_sg.name]
}

resource "aws_instance" "video_streaming_server_2" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_subnet_public.id
  security_groups = [aws_security_group.video_streaming_sg.name]
}

resource "aws_lb_target_group_attachment" "video_streaming_tg_attachment_1" {
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming_server_1.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "video_streaming_tg_attachment_2" {
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming_server_2.id
  port             = 80
}
```

This Terraform configuration sets up the necessary AWS resources to support a video streaming site with load balancing. It includes a VPC, a public subnet, a security group, an Application Load Balancer, a target group, and two EC2 instances. The ALB distributes incoming HTTP traffic to the EC2 instances via the target group.

