### Description of the Terraform Program

This Terraform program sets up a PostgreSQL 15 instance on AWS RDS within specific public subnets for running Airbyte connector test cases. The configuration includes the necessary parameters to ensure low maintenance and proper management of the RDS instance. The program also creates an IAM role with the required permissions for the RDS instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_subnet_group_name" {
  description = "The name of the DB subnet group"
  default     = "airbyte-postgres-subnet-group"
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance"
  default     = "airbyte-postgres-instance"
}

variable "db_name" {
  description = "The name of the database"
  default     = "airbyte_db"
}

variable "db_username" {
  description = "The username for the database"
  default     = "airbyte_user"
}

variable "db_password" {
  description = "The password for the database"
  default     = "securepassword123"
}

variable "instance_class" {
  description = "The instance class for the RDS instance"
  default     = "db.t3.medium"
}

variable "allocated_storage" {
  description = "The allocated storage for the RDS instance"
  default     = 20
}

variable "backup_retention_period" {
  description = "The backup retention period in days"
  default     = 7
}

variable "backup_window" {
  description = "The backup window"
  default     = "07:00-09:00"
}

resource "aws_iam_role" "rds_iam_role" {
  name = "airbyte-rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_db_subnet_group" "airbyte_postgres_subnet_group" {
  name       = var.db_subnet_group_name
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]  # Replace with actual subnet IDs

  tags = {
    Name = "airbyte-postgres-subnet-group"
  }
}

resource "aws_db_instance" "airbyte_postgres" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = "15"
  instance_class          = var.instance_class
  allocated_storage       = var.allocated_storage
  db_subnet_group_name    = aws_db_subnet_group.airbyte_postgres_subnet_group.name
  username                = var.db_username
  password                = var.db_password
  db_name                 = var.db_name
  backup_retention_period = var.backup_retention_period
  backup_window           = var.backup_window
  iam_database_authentication_enabled = true
  skip_final_snapshot     = true

  vpc_security_group_ids = ["sg-0123456789abcdef0"]  # Replace with actual security group ID

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}
```

### Notes
- Ensure that the subnet IDs and security group IDs are replaced with actual values from your AWS account.
- The `db_password` variable should be securely managed, possibly using Terraform's `sensitive` attribute or external secrets management tools.
- The `skip_final_snapshot` attribute is set to `true` to avoid creating a final snapshot when the RDS instance is deleted. Adjust this setting based on your requirements.

