  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "aurora_subnet_3" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "aurora_proxy_role" {
  name = "aurora-proxy-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "aurora_proxy_policy" {
  name        = "aurora-proxy-policy"
  description = "Policy for Aurora Proxy"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_aurora_proxy_policy" {
  policy_arn = aws_iam_policy.aurora_proxy_policy.arn
  role       = aws_iam_role.aurora_proxy_role.name
}

resource "aws_rds_cluster" "aurora_cluster" {
  engine               = "aurora-mysql"
  engine_version       = "8.0.mysql_aurora.3.02.1"
  cluster_identifier   = "aurora-cluster-demo"
  availability_zones = [aws_subnet.aurora_subnet_1.availability_zone, aws_subnet.aurora_subnet_2.availability_zone, aws_subnet.aurora_subnet_3.availability_zone]
  database_name        = "mydb"
  master_username      = "admin"
  master_password      = "securepassword123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  iam_roles            = [aws_iam_role.aurora_proxy_role.arn]
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id, aws_subnet.aurora_subnet_3.id]
}

resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-proxy"
  db_cluster_identifier    = aws_rds_cluster.aurora_cluster.id
  engine_family          = "MYSQL8"
  idle_client_timeout    = 1800
  require_tls            = true
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id, aws_subnet.aurora_subnet_3.id]
  auth {
    auth_scheme = "SECRETS"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.aurora_db_credentials.arn
  }
}

resource "aws_secretsmanager_secret" "aurora_db_credentials" {
  name = "aurora-db-credentials"
}

resource "aws_secretsmanager_secret_version" "aurora_db_credentials_version" {
  secret_id     = aws_secretsmanager_secret.aurora_db_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = "securepassword123"
  })
}
