provider "aws" {
  region = "us-east-1"
}

# Create a Lightsail storage unit
resource "aws_lightsail_bucket" "lightsail_storage_unit" {
  bundle_id = "small_1_0"
  name      = "my-lightsail-storage-unit"
}

# Create a Lightsail compute service
resource "aws_lightsail_instance" "lightsail_compute_service" {
  availability_zone = "us-east-1a"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_1_0"
  name              = "my-lightsail-compute-service"
}

# Create an IAM role for accessing the Lightsail storage unit
resource "aws_iam_role" "lightsail_storage_access_role" {
  name = "LightsailStorageAccessRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy allowing access to the Lightsail storage unit
resource "aws_iam_policy" "lightsail_storage_access_policy" {
  name        = "LightsailStorageAccessPolicy"
  description = "Policy allowing access to the Lightsail storage unit"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lightsail:GetBucket",
          "lightsail:PutBucket",
          "lightsail:DeleteBucket",
          "lightsail:GetObject",
          "lightsail:PutObject",
          "lightsail:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:lightsail:*:*:Bucket/*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_storage_policy_to_role" {
  policy_arn = aws_iam_policy.lightsail_storage_access_policy.arn
  role       = aws_iam_role.lightsail_storage_access_role.name
}

# Create an access key for the Lightsail storage unit
resource "aws_lightsail_bucket_access_key" "storage_access_key" {
  bucket_name = aws_lightsail_bucket.lightsail_storage_unit.name
}

# Upload a sample file to the Lightsail storage unit
resource "aws_s3_object" "sample_file" {
  bucket = aws_lightsail_bucket.lightsail_storage_unit.name
  key    = "sample.txt"
  source = "path/to/sample.txt"
}

# Set ACL for the sample file
resource "aws_s3_object_acl" "sample_file_acl" {
  bucket = aws_s3_object.sample_file.bucket
  key    = aws_s3_object.sample_file.key
  acl    = "private"
}

# Create a version for the sample file
resource "aws_s3_object" "sample_file_version" {
  bucket = aws_lightsail_bucket.lightsail_storage_unit.name
  key    = aws_s3_object.sample_file.key
  source = "path/to/sample.txt"
  etag   = md5(file("path/to/sample.txt"))
}

# Set ACL for the sample file version
resource "aws_s3_object_acl" "sample_file_version_acl" {
  bucket = aws_s3_object.sample_file_version.bucket
  key    = aws_s3_object.sample_file_version.key
  acl    = "private"
}
```

