### Description

This Terraform program creates an S3 bucket for long-term data storage with versioning enabled for backup purposes. It also sets up an IAM role and policy for S3 backup operations and configures lifecycle rules for data management.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "long_term_data_storage" {
  bucket = "long-term-data-storage-bucket"
  acl    = "private"
  tags = {
    Name        = "LongTermDataStorage"
    Environment = "production"
  }
}

resource "aws_s3_bucket_versioning" "long_term_data_storage_versioning" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "s3_backup_role" {
  name = "S3BackupRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_backup_policy" {
  name        = "S3BackupPolicy"
  description = "Policy for S3 backup operations"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.long_term_data_storage.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_backup_policy_to_role" {
  policy_arn = aws_iam_policy.s3_backup_policy.arn
  role       = aws_iam_role.s3_backup_role.name
}

resource "aws_s3_bucket_lifecycle_configuration" "long_term_data_storage_lifecycle" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  rule {
    id     = "ExpireOldObjects"
    status = "Enabled"
    prefix = ""
    expiration {
      days = 365
    }
  }
}
```

This configuration sets up an S3 bucket with versioning, an IAM role with a policy for backup operations, and lifecycle rules to manage data retention.

