### Description
This Terraform program creates an Application Load Balancer (ALB) in AWS. The ALB is configured to be internet-facing, uses two subnets, and has access logging enabled. The program also includes the necessary dependencies such as subnets, security groups, and an S3 bucket for storing access logs.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "lb_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "my-alb-logs-bucket"
}

resource "aws_lb" "app_lb" {
  name               = "my-app-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  access_logs {
    bucket = aws_s3_bucket.lb_logs.bucket
    prefix = "alb-logs/"
    enabled = true
  }

  enable_deletion_protection = true
}
```

This Terraform configuration sets up an Application Load Balancer in the `us-west-2` region. It includes a VPC with two public subnets, a security group allowing HTTP traffic, an S3 bucket for access logs, and the ALB itself configured with access logging enabled.

