### Description
This Terraform program creates an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The program includes the following resources:

1. **aws_lb**: An Application Load Balancer.
2. **aws_lb_target_group**: A target group for the load balancer.
3. **aws_lb_listener**: A listener for the load balancer that forwards traffic to the target group.
4. **aws_lb_target_group_attachment**: Attachments to add EC2 instances to the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public.id]

  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "my-alb-logs/"
    enabled = true
  }

  enable_deletion_protection = true
  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    interval            = 30
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.my_application_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.my_target_group.arn
  }
}

resource "aws_lb_target_group_attachment" "my_target_group_attachment" {
  target_group_arn = aws_lb_target_group.my_target_group.arn
  target_id        = aws_instance.my_instance.id
  port             = 80
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "my-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "my-public-subnet"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "my-lb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-lb-sg"
  }
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "my-alb-logs-bucket"
  acl    = "log-delivery-write"

  tags = {
    Name = "my-alb-logs-bucket"
  }
}

resource "aws_instance" "my_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "my-instance"
  }
}
```

### Explanation
- **aws_lb**: Defines an Application Load Balancer with access logs enabled.
- **aws_lb_target_group**: Defines a target group with a health check configuration.
- **aws_lb_listener**: Defines a listener that forwards traffic to the target group.
- **aws_lb_target_group_attachment**: Attaches an EC2 instance to the target group.
- **aws_vpc**, **aws_subnet**, **aws_security_group**, **aws_s3_bucket**, and **aws_instance**: Supporting resources to create a VPC, subnet, security group, S3 bucket, and EC2 instance respectively.

