}

variable "vpc_id" {
  description = "The ID of the VPC where the load balancers will be created."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the load balancers will be deployed."
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the load balancers."
  default     = "sg-12345678"
}

