  subnets            = var.subnet_ids
  security_groups    = [var.security_group_id]
  internal           = true
}

resource "aws_lb_target_group" "nlb_target_group" {
  name     = "nlb-target-group"
  port     = 80
  protocol = "TCP"
  vpc_id   = var.vpc_id

  health_check {
    protocol = "TCP"
    port     = 80
  }
}

resource "aws_lb_listener" "nlb_target_listener" {
  load_balancer_arn = aws_lb.nlb_target.arn
  protocol          = "TCP"
  port              = 80

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_target_group.arn
  }
}

resource "aws_lb" "nlb_forwarder" {
  name               = "nlb-forwarder"
  load_balancer_type = "application"
  subnets            = var.subnet_ids
  security_groups    = [var.security_group_id]
}

resource "aws_lb_listener" "nlb_forwarder_listener" {
