Description:
The Terraform program defines an Application Load Balancer (ALB) with a fixed-response action. The ALB is configured to listen on port 80 and respond with a "Hello, World!" message for the default action. Additionally, a listener rule is set up to respond with a "Fixed Response Rule" message when the path pattern matches "/fixed". The ALB is associated with a target group that includes an EC2 instance. The necessary security groups, subnets, VPC, and S3 bucket for logging are also created.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public.id]

  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "my-alb-logs/"
    enabled = true
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, World!"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "my_listener_rule" {
  listener_arn = aws_lb_listener.my_listener.arn
  priority     = 1

  action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed Response Rule"
      status_code  = "404"
    }
  }

  condition {
    field  = "path-pattern"
    values = ["/fixed"]
  }
}

resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_subnet.public.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group_attachment" "my_target_group_attachment" {
  target_group_arn = aws_lb_target_group.my_target_group.arn
  target_id        = aws_instance.my_instance.id
  port             = 80
}

resource "aws_instance" "my_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t2.micro
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "my-instance"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "my-lb-sg"
  description = "Security group for my ALB"
  vpc_id      = aws_subnet.public.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-lb-sg"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "my-public-subnet"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "my-vpc"
  }
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "my-alb-logs-bucket"
  acl    = "log-delivery-write"

  tags = {
    Name = "my-alb-logs-bucket"
  }
}
