  load_balancer_arn = aws_lb.my_application_lb.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-Ext-2018-06"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed response content"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "my_listener_rule" {
  listener_arn = aws_lb_listener.my_listener.arn
  priority     = 1

  action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.my_user_pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.my_user_pool_client.id
      user_pool_domain    = "my-user-pool-domain.auth.us-west-2.amazoncognito.com"
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}

resource "aws_cognito_user_pool" "my_user_pool" {
  name = "my_user_pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length                = 8
    require_lowercase             = true
    require_numbers               = true
    require_symbols               = true
    require_uppercase             = true
    temporary_password_validity_days = 7
  }

  schema {
    attribute_data_type = "String"
    name                = "email"
    required            = true
  }

  schema {
    attribute_data_type = "String"
    name                = "phone_number"
    required            = false
  }

  tags = {
    Name = "MyUserPool"
  }
}

resource "aws_cognito_user_pool_client" "my_user_pool_client" {
  name         = "my_user_pool_client"
  user_pool_id = aws_cognito_user_pool.my_user_pool.id

  allowed_oauth_flows        = ["code", "implicit"]
  allowed_oauth_scopes       = ["phone", "email", "openid", "profile"]
  callback_urls              = ["https://example.com/callback"]
  default_redirect_uri       = "https://example.com/home"
  logout_urls                = ["https://example.com/logout"]
  supported_identity_providers = ["COGNITO"]

  generate_secret = true

  tags = {
    Name = "MyUserPoolClient"
  }
}

resource "aws_cognito_identity_pool" "my_identity_pool" {
  identity_pool_name               = "my_identity_pool"
  allow_unauthenticated_identities = false
  supported_login_providers        = {
    "cognito-idp.${var.region}.amazonaws.com/${aws_cognito_user_pool.my_user_pool.id}" = ""
  }

  tags = {
    Name = "MyIdentityPool"
  }
}

resource "aws_cognito_identity_pool_roles_attachment" "my_identity_pool_roles" {
  identity_pool_id = aws_cognito_identity_pool.my_identity_pool.id
  roles = {
    authenticated = aws_iam_role.my_lb_role.arn
  }
}

resource "aws_iam_role" "my_lb_role" {
  name = "my_lb_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.my_identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "my_lb_policy" {
  name        = "my_lb_policy"
  description = "Policy for Load Balancer to interact with Cognito"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cognito-idp:DescribeUserPoolClient",
          "cognito-idp:ListUserPoolClients",
          "cognito-idp:DescribeUserPoolDomain",
          "cognito-idp:DescribeIdentityProvider",
          "cognito-idp:ListIdentityProviders",
          "cognito-idp:GetUser",
          "cognito-idp:InitiateAuth",
          "cognito-idp:RespondToAuthChallenge"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "my_lb_policy_attachment" {
  policy_arn = aws_iam_policy.my_lb_policy.arn
  role       = aws_iam_role.my_lb_role.name
}
