### Description
The Terraform program below creates a memory-optimized PostgreSQL RDS instance in AWS. It includes the necessary VPC, subnet, security group, DB subnet group, IAM role, and RDS instance. The configuration ensures that all resources are properly associated and that the security group allows necessary inbound and outbound traffic for PostgreSQL.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "memory_optimized_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "memory_optimized_subnet" {
  vpc_id                  = aws_vpc.memory_optimized_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "memory_optimized_sg" {
  vpc_id = aws_vpc.memory_optimized_vpc.id
  name   = "memory_optimized_sg"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "memory_optimized_subnet_group" {
  name       = "memory_optimized_subnet_group"
  subnet_ids = [aws_subnet.memory_optimized_subnet.id]
}

resource "aws_iam_role" "memory_optimized_rds_role" {
  name = "memory_optimized_rds_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "memory_optimized_rds_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.memory_optimized_rds_role.name
}

resource "aws_db_instance" "memory_optimized_postgresql" {
  identifier              = "memory-optimized-postgresql"
  instance_class          = "db.r6g.large"
  engine                  = "postgres"
  engine_version          = "13.7"
  allocated_storage       = 20
  username                = "admin"
  password                = "securepassword"
  db_subnet_group_name    = aws_db_subnet_group.memory_optimized_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.memory_optimized_sg.id]
  skip_final_snapshot     = true
  iam_database_authentication_enabled = true
}
```

This Terraform configuration sets up a memory-optimized PostgreSQL RDS instance in the `us-west-2` region. It includes a VPC, subnet, security group, DB subnet group, IAM role, and RDS instance, ensuring all dependencies are correctly configured.

