### Description
This Terraform program sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled. It also creates an internet gateway and a route table for outbound internet access, all tagged with a variable name.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  type        = string
  description = "The name to tag the VPC, internet gateway, and route table with."
  default     = "my-dedicated-vpc"
}

resource "aws_vpc" "dedicated_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "dedicated"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.dedicated_vpc.id
  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route_table" "outbound_route_table" {
  vpc_id = aws_vpc.dedicated_vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet_gateway.id
  }
  tags = {
    Name = var.vpc_name
  }
}
```

This configuration creates a VPC with the specified CIDR block, instance tenancy, DNS support, and DNS hostnames. It then attaches an internet gateway to the VPC and sets up a route table with a route to the internet gateway for outbound internet access. All resources are tagged with the provided `vpc_name` variable.

