  ingress {
    rule_no   = 100
    action    = "allow"
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no   = 200
    action    = "allow"
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no   = 300
